#ifdef _WIN32
typedef void* PlatFile;
#define PLAT_INVALID_FILE ((void*)-1)
#else
typedef int PlatFile;
#define PLAT_INVALID_FILE (-1)
#endif

static usize pal_strlen(const char* s)
{
#ifdef _WIN32
    const char* p = s;
    while (*p) p++;
    return (usize)(p - s);
#else
    return (usize)strlen(s);
#endif
}

static void pal_memcpy(void* dst, const void* src, usize n)
{
#ifdef _WIN32
    char* d = (char*)dst;
    const char* s = (const char*)src;
    while (n--) *d++ = *s++;
#else
    memcpy(dst, src, (size_t)n);
#endif
}

static void pal_reverse(char* buf, int len)
{
    int i = 0;
    int j = len - 1;
    while (i < j) {
        char t = buf[i];
        buf[i] = buf[j];
        buf[j] = t;
        i++;
        j--;
    }
}

static int pal_u64_to_str_buf(u64 value, char* buf, int bufsize)
{
    int i;
    if (bufsize <= 0) return 0;
    if (value == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return 1;
    }
    i = 0;
    while (value > 0 && i < bufsize - 1) {
        buf[i++] = '0' + (char)(value % 10);
        value /= 10;
    }
    buf[i] = '\0';
    pal_reverse(buf, i);
    return i;
}

void pal_print_stderr(const char* msg, usize len)
{
#ifdef _WIN32
    HANDLE h;
    DWORD written;
    if (!msg || len == 0) return;
    h = GetStdHandle(STD_ERROR_HANDLE);
    if (h == INVALID_HANDLE_VALUE || h == NULL) return;
    if (!WriteConsoleA(h, msg, (DWORD)len, &written, NULL))
        WriteFile(h, msg, (DWORD)len, &written, NULL);
#else
    write(2, msg, (size_t)len);
#endif
}

void pal_print_stdout(const char* msg, usize len)
{
#ifdef _WIN32
    HANDLE h;
    DWORD written;
    if (!msg || len == 0) return;
    h = GetStdHandle(STD_OUTPUT_HANDLE);
    if (h == INVALID_HANDLE_VALUE || h == NULL) return;
    if (!WriteConsoleA(h, msg, (DWORD)len, &written, NULL))
        WriteFile(h, msg, (DWORD)len, &written, NULL);
#else
    write(1, msg, (size_t)len);
#endif
}

void pal_abort(void)
{
#ifdef _WIN32
    TerminateProcess(GetCurrentProcess(), 3);
#else
    abort();
#endif
}

int pal_i64_to_str(i64 value, char* buf, int bufsize)
{
    u64 uval;
    int is_neg;
    int dlen;
    if (bufsize <= 0) return 0;
    if (value == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return 1;
    }
    is_neg = (value < 0) ? 1 : 0;
    uval = is_neg ? (u64)(-(value + 1)) + 1 : (u64)value;
    if (is_neg) {
        buf[0] = '-';
        dlen = pal_u64_to_str_buf(uval, buf + 1, bufsize - 1);
        return dlen + 1;
    }
    return pal_u64_to_str_buf(uval, buf, bufsize);
}

int pal_u64_to_str(u64 value, char* buf, int bufsize)
{
    return pal_u64_to_str_buf(value, buf, bufsize);
}

int pal_f64_to_str(f64 value, char* buf, int bufsize)
{
    int int_len;
    int i;
    f64 frac_part;
    i64 int_part;
    u64 frac_int;
    int pos;
    if (bufsize < 2) {
        if (bufsize == 1) buf[0] = '\0';
        return 0;
    }
    if (value < 0.0) {
        buf[0] = '-';
        pos = 1;
        value = -value;
    } else {
        pos = 0;
    }
    int_part = (i64)value;
    int_len = pal_i64_to_str(int_part, buf + pos, bufsize - pos);
    if (int_len <= 0) return 0;
    pos += int_len;
    buf[pos++] = '.';
    frac_part = value - (f64)int_part;
    i = 0;
    while (i < 6 && pos < bufsize - 1) {
        frac_part *= 10.0;
        frac_int = (u64)frac_part;
        buf[pos++] = '0' + (char)(frac_int % 10);
        frac_part -= (f64)frac_int;
        i++;
    }
    while (pos > 0 && buf[pos - 1] == '0') pos--;
    if (buf[pos - 1] == '.') pos++;
    buf[pos] = '\0';
    return pos;
}

PlatFile pal_file_open(const char* path, int flags) {
#ifdef _WIN32
    HANDLE h = CreateFileA(path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS,
                           FILE_ATTRIBUTE_NORMAL, NULL);
    if (h == INVALID_HANDLE_VALUE) return PLAT_INVALID_FILE;
    return h;
#else
    if (!path) return PLAT_INVALID_FILE;
    return open(path, O_WRONLY | O_CREAT | O_TRUNC | flags, 0644);
#endif
}
int pal_file_write(PlatFile fd, const char* buf, unsigned int len) {
#ifdef _WIN32
    HANDLE h = (HANDLE)fd; DWORD w = 0;
    if (!buf || !WriteFile(h, buf, (DWORD)len, &w, NULL)) return -1;
    return (int)w;
#else
    size_t off = 0; if (!buf) return -1;
    while (off < (size_t)len) {
        ssize_t n = write(fd, buf + off, (size_t)len - off);
        if (n <= 0) return -1;
        off += (size_t)n;
    }
    return (int)off;
#endif
}
int pal_file_close(PlatFile fd) {
#ifdef _WIN32
    return CloseHandle((HANDLE)fd) ? 0 : -1;
#else
    return close(fd);
#endif
}

int pal_dir_exists(const char* path)
{
#ifdef _WIN32
    DWORD attr;
    attr = GetFileAttributesA(path);
    return (attr != INVALID_FILE_ATTRIBUTES && (attr & FILE_ATTRIBUTE_DIRECTORY));
#else
    struct stat sb;
    if (path == 0 || stat(path, &sb) != 0) return 0;
    return (sb.st_mode & 0040000) != 0;
#endif
}

/* pal_get_default_lib_path: compute the compiler-binary-relative default
 * install path <exe_dir>/lib. Win9x-primary via GetModuleFileNameA (kernel32,
 * present since Win95); Linux best-effort via readlink("/proc/self/exe").
 * Returns the length of the written path (excluding NUL), or 0 on failure. */
int pal_get_default_lib_path(char* buf, int bufsize)
{
#ifdef _WIN32
    DWORD n;
    int i;
    int dir_len;
    if (!buf || bufsize < 2) return 0;
    n = GetModuleFileNameA(NULL, buf, (DWORD)bufsize);
    if (n == 0 || n >= (DWORD)bufsize) return 0;
    i = (int)n - 1;
    while (i >= 0 && buf[i] != '\\' && buf[i] != '/') i--;
    dir_len = i;
#else
    ssize_t n;
    int i;
    int dir_len;
    if (!buf || bufsize < 2) return 0;
    n = readlink("/proc/self/exe", buf, (size_t)bufsize - 1);
    if (n <= 0 || n >= (ssize_t)bufsize - 1) return 0;
    buf[n] = '\0';
    i = (int)n - 1;
    while (i >= 0 && buf[i] != '/') i--;
    dir_len = i;
#endif
    if (dir_len < 0) return 0;
    if (dir_len + 5 > bufsize) return 0;
    buf[dir_len] = '/';
    buf[dir_len + 1] = 'l';
    buf[dir_len + 2] = 'i';
    buf[dir_len + 3] = 'b';
    buf[dir_len + 4] = '\0';
    return dir_len + 4;
}

